// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const { createQueryBrowserHarness } = require('./query-browser-harness.js');

const queryPage = 'http://localhost:8080/rdf4j-workbench/repositories/test/query';
const draftKey = 'workbench:query-draft:test-session:/rdf4j-workbench/repositories/test/query';

function sharedUrl(query, search = '') {
    return queryPage + search + '#' + new URLSearchParams({ query }).toString();
}

function storage(initial = []) {
    const values = new Map(initial);
    return {
        values,
        getItem: (key) => values.has(key) ? values.get(key) : null,
        setItem: (key, value) => values.set(key, String(value)),
        removeItem: (key) => values.delete(key)
    };
}

function createHarness(options = {}) {
    const harness = createQueryBrowserHarness(Object.assign({ query: '' }, options, {
        globals: Object.assign({ URLSearchParams }, options.globals)
    }));
    // The shared browser fixture models href/search; expose the standard hash accessor for these navigation tests.
    Object.defineProperty(harness.document.location, 'hash', {
        get() { return new URL(harness.document.location.href).hash; },
        set(value) {
            const url = new URL(harness.document.location.href);
            url.hash = value;
            harness.document.location.href = url.href;
        }
    });
    return harness;
}

function navigateHash(harness, query) {
    const oldURL = harness.document.location.href;
    const url = new URL(oldURL);
    url.hash = new URLSearchParams({ query }).toString();
    harness.document.location.href = url.href;
    harness.window.dispatchEvent({ type: 'hashchange', oldURL, newURL: url.href });
}

test('a shared query fragment loads the editor and persists the draft without executing it', () => {
    const query = 'SELECT * WHERE { ?shared ?p ?o } LIMIT 17';
    const sessionStorage = storage();
    const harness = createHarness({ href: sharedUrl(query), window: { sessionStorage } });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
    assert.equal(sessionStorage.values.get(draftKey), query);
    assert.equal(harness.getJSONRequests.length, 0, 'the fragment contains text, not a stored query reference');
    assert.equal(harness.requestsByAction('exec').length, 0, 'opening a link must not run the query');
    assert.equal(harness.pendingExplainRequests.length, 0);
});

test('a shared query fragment overrides an old saved-query URL and the page model', () => {
    const query = 'ASK { ?shared ?p ?o }';
    const harness = createHarness({
        href: sharedUrl(query, '?query=old-saved-query&ref=id'),
        query: 'SELECT * WHERE { ?pageModel ?p ?o }',
        getJSONResponses: [{ queryText: 'ASK { ?oldSavedQuery ?p ?o }' }]
    });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
    assert.equal(harness.getJSONRequests.length, 0, 'stale search parameters must not fetch a different query');
});

test('a shared query fragment overrides an existing session draft', () => {
    const query = 'ASK { ?shared ?p ?o }';
    const sessionStorage = storage([[draftKey, 'ASK { ?draft ?p ?o }']]);
    const harness = createHarness({ href: sharedUrl(query), window: { sessionStorage } });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
    assert.equal(sessionStorage.values.get(draftKey), query);
});

test('shared query text preserves encoded fragments, ampersands, plus signs, percent signs and Unicode', () => {
    const query = 'PREFIX ex: <https://example.org/ns#>\nSELECT ?s WHERE {\n'
        + '  ?s ex:label "Håvard + café & 100% = ? #" .\n  FILTER(CONTAINS(STR(?s), "a+b"))\n}';
    const harness = createHarness({ href: sharedUrl(query) });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
});

test('shared editor text preserves leading and trailing whitespace on load and hash navigation', () => {
    const sessionStorage = storage();
    const query = '\n  SELECT * WHERE { ?s ?p ?o }\n\t';
    const harness = createHarness({ href: sharedUrl(query), window: { sessionStorage } });
    harness.runPageLoad();

    assert.equal(harness.yasqeState.instances.query.getValue(), query);
    assert.equal(sessionStorage.values.get(draftKey), query);
    const changed = ' \nASK { ?changed ?p ?o }\n ';
    navigateHash(harness, changed);
    assert.equal(harness.yasqeState.instances.query.getValue(), changed);
    assert.equal(sessionStorage.values.get(draftKey), changed);
});

test('an explicitly empty shared query clears stale page text and session drafts', () => {
    const sessionStorage = storage([[draftKey, 'ASK { ?draft ?p ?o }']]);
    const harness = createHarness({ href: sharedUrl(''), query: 'ASK { ?page ?p ?o }',
        window: { sessionStorage } });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), '');
    assert.ok(!sessionStorage.values.get(draftKey), 'an old draft must not reappear on reload');
});

test('changing a shared fragment in the mounted page updates only the primary editor', () => {
    const sessionStorage = storage();
    const harness = createHarness({ href: queryPage, query: 'ASK { ?original ?p ?o }',
        window: { sessionStorage } });
    harness.runPageLoad();
    harness.context.workbench.query.toggleCompareMode();
    const comparison = 'SELECT * WHERE { ?comparison ?p ?o }';
    harness.yasqeState.instances['query-compare'].setValue(comparison);
    const query = 'ASK { ?sharedLater ?p ?o }';
    const explanationsBefore = harness.pendingExplainRequests.length;
    navigateHash(harness, query);

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
    assert.equal(harness.yasqeState.instances['query-compare'].getValue(), comparison);
    assert.equal(sessionStorage.values.get(draftKey), query);
    assert.equal(harness.requestsByAction('exec').length, 0);
    assert.equal(harness.pendingExplainRequests.length, explanationsBefore, 'loading a link does not auto-explain');
});

test('a shared query does not replace the unchanged comparison seed', () => {
    const original = 'ASK { ?original ?p ?o }';
    const harness = createHarness({ href: queryPage, query: original });
    harness.runPageLoad();
    harness.context.workbench.query.toggleCompareMode();
    assert.equal(harness.yasqeState.instances['query-compare'].getValue(), original);

    navigateHash(harness, 'ASK { ?sharedLater ?p ?o }');

    assert.equal(harness.context.workbench.query.getQueryValue(), 'ASK { ?sharedLater ?p ?o }');
    assert.equal(harness.yasqeState.instances['query-compare'].getValue(), original);
});

test('a shared query does not claim an old page-model explanation as its own', () => {
    const harness = createHarness({ href: sharedUrl('ASK { ?newQuery ?p ?o }'),
        query: 'ASK { ?previousQuery ?p ?o }', initialExplanation: 'Plan for the previous query' });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), 'ASK { ?newQuery ?p ?o }');
    assert.match(harness.getText('query-explanation-status'), /stale/i);
    assert.equal(harness.pendingExplainRequests.length, 0);
});

test('a resumed Query page consumes a different shared fragment but retains edits for the same fragment', () => {
    const firstQuery = 'ASK { ?first ?p ?o }';
    const harness = createHarness({ href: sharedUrl(firstQuery) });
    const cleanup = harness.runPageLoad();
    harness.context.workbench.query.setQueryValue('ASK { ?myEdit ?p ?o }');
    cleanup.suspend();
    cleanup.resume();
    assert.equal(harness.context.workbench.query.getQueryValue(), 'ASK { ?myEdit ?p ?o }',
        'returning to an unchanged address preserves the live editor');

    cleanup.suspend();
    const nextQuery = 'ASK { ?nextLink ?p ?o }';
    navigateHash(harness, nextQuery);
    assert.equal(harness.context.workbench.query.getQueryValue(), 'ASK { ?myEdit ?p ?o }',
        'a suspended page does not react to navigation on another page');
    cleanup.resume();
    assert.equal(harness.context.workbench.query.getQueryValue(), nextQuery);
    cleanup();
    assert.equal(harness.window.listenerCount('hashchange'), 0, 'disposal removes its hash listener');
});

test('a saved-query response cannot replace a newer shared query', () => {
    const harness = createHarness({ href: queryPage + '?query=stored&ref=id', deferGetJSON: true,
        getJSONResponses: [{ queryText: 'ASK { ?outdated ?p ?o }' }] });
    harness.runPageLoad();
    assert.equal(harness.getJSONRequests.length, 1);
    const query = 'ASK { ?newShared ?p ?o }';
    navigateHash(harness, query);
    harness.resolveNextGetJSON();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
});

test('ordinary document anchors retain the mounted query', () => {
    const query = 'ASK { ?draft ?p ?o }';
    const harness = createHarness({ href: queryPage, query });
    harness.runPageLoad();
    harness.document.location.href = queryPage + '#query-output';
    harness.window.dispatchEvent({ type: 'hashchange' });

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
    assert.equal(harness.getJSONRequests.length, 0);
});

test('legacy query-string links still accept an unencoded IRI fragment', () => {
    const query = 'PREFIX ex: <https://example.org/ns#> SELECT ?s WHERE { ?s ex:p ?o }';
    const harness = createHarness({ href: queryPage + '?query=' + query });
    harness.runPageLoad();

    assert.equal(harness.context.workbench.query.getQueryValue(), query);
});
